public final class DifferentialOdometry {
    private final double countsPerInch;
    private int previousLeft;
    private int previousRight;
    private boolean initialized;
    private double x;
    private double y;
    private final double startHeadingRadians;
    private double initialRawYaw;

    public DifferentialOdometry(double countsPerInch, double startX, double startY,
                                double startHeadingRadians) {
        if (!Double.isFinite(countsPerInch) || countsPerInch <= 0.0
                || !Double.isFinite(startX) || !Double.isFinite(startY)
                || !Double.isFinite(startHeadingRadians)) {
            throw new IllegalArgumentException("Finite pose and positive scale required");
        }
        this.startHeadingRadians = startHeadingRadians;
        this.countsPerInch = countsPerInch;
        this.x = startX;
        this.y = startY;
    }

    public void update(int leftTicks, int rightTicks, double headingRadians) {
        if (!Double.isFinite(headingRadians)) throw new IllegalArgumentException("Finite yaw required");
        if (!initialized) {
            previousLeft = leftTicks;
            previousRight = rightTicks;
            initialRawYaw = headingRadians;
            initialized = true; // First call records encoder and yaw baselines.
            return;
        }

        double left = (leftTicks - previousLeft) / countsPerInch;
        double right = (rightTicks - previousRight) / countsPerInch;
        previousLeft = leftTicks;
        previousRight = rightTicks;

        double forward = (left + right) / 2.0;
        double fieldHeading = startHeadingRadians
            + Math.atan2(Math.sin(headingRadians - initialRawYaw),
                         Math.cos(headingRadians - initialRawYaw));
        x += forward * Math.cos(fieldHeading);
        y += forward * Math.sin(fieldHeading);
    }

    public double x() { return x; }
    public double y() { return y; }
}
