class TrapezoidProfile(distance: Double, maxVelocity: Double, maxAcceleration: Double) {
    private val distance = distance
    private val acceleration = maxAcceleration
    private val peakVelocity: Double
    private val accelerationTime: Double
    private val cruiseTime: Double
    private val totalTime: Double

    init {
        require(distance.isFinite() && distance >= 0.0)
        require(maxVelocity.isFinite() && maxVelocity > 0.0)
        require(maxAcceleration.isFinite() && maxAcceleration > 0.0)
        val timeToMaxVelocity = maxVelocity / maxAcceleration
        val distanceToMaxVelocity = 0.5 * maxAcceleration * timeToMaxVelocity * timeToMaxVelocity
        if (2.0 * distanceToMaxVelocity >= this.distance) {
            peakVelocity = sqrt(this.distance * maxAcceleration)
            accelerationTime = peakVelocity / maxAcceleration
            cruiseTime = 0.0
        } else {
            peakVelocity = maxVelocity
            accelerationTime = timeToMaxVelocity
            val cruiseDistance = this.distance - 2.0 * distanceToMaxVelocity
            cruiseTime = cruiseDistance / peakVelocity
        }
        totalTime = 2.0 * accelerationTime + cruiseTime
    }

    fun sample(seconds: Double): ProfileState {
        require(seconds.isFinite())
        val t = max(0.0, min(seconds, totalTime))
        val accelerationDistance = 0.5 * acceleration * accelerationTime * accelerationTime
        if (t < accelerationTime) {
            return ProfileState(0.5 * acceleration * t * t, acceleration * t)
        }
        if (t < accelerationTime + cruiseTime) {
            val cruiseElapsed = t - accelerationTime
            return ProfileState(accelerationDistance + peakVelocity * cruiseElapsed, peakVelocity)
        }

        val decelerationRemaining = totalTime - t
        return ProfileState(
            distance - 0.5 * acceleration * decelerationRemaining * decelerationRemaining,
            acceleration * decelerationRemaining
        )
    }

    fun totalTime() = totalTime
